-- What PostgreSQL 18 adds to script-hostile-pg.sql: named not-null constraints, virtual generated
-- columns, NOT ENFORCED, and WITHOUT OVERLAPS.
CREATE TABLE app.nn (
  plain int NOT NULL,
  named int CONSTRAINT nn_named NOT NULL,
  "Mi xed" int CONSTRAINT "Odd ""nn""" NOT NULL,
  unchecked int,
  uninherited int NOT NULL NO INHERIT,
  named_uninherited int CONSTRAINT nn_named_uninherited NOT NULL NO INHERIT,
  commented int NOT NULL,
  both_unchecked_uninherited int
);
ALTER TABLE app.nn ADD CONSTRAINT nn_unchecked NOT NULL unchecked NOT VALID;
ALTER TABLE app.nn ADD CONSTRAINT nn_both NOT NULL both_unchecked_uninherited NO INHERIT NOT VALID;
COMMENT ON CONSTRAINT nn_commented_not_null ON app.nn IS 'a not-null with the default name';
COMMENT ON CONSTRAINT nn_named ON app.nn IS 'a named not-null';
COMMENT ON CONSTRAINT nn_unchecked ON app.nn IS 'a not-null checked later';

CREATE TABLE app.nn_pk (id int CONSTRAINT nn_pk_named NOT NULL PRIMARY KEY);
CREATE TABLE app.nn_serial (id serial CONSTRAINT nn_serial_named NOT NULL);
CREATE TABLE app.nn_identity (id int GENERATED ALWAYS AS IDENTITY CONSTRAINT nn_identity_named NOT NULL);
CREATE TABLE app.nn_identity_uninherited (id int NOT NULL NO INHERIT);
ALTER TABLE app.nn_identity_uninherited ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (START WITH 9);
ALTER SEQUENCE app.nn_identity_uninherited_id_seq SET UNLOGGED;
CREATE TABLE app.nn_long_name_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa (long_column_bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb int NOT NULL);
CREATE TABLE app.nn_renamed (before_rename int NOT NULL);
ALTER TABLE app.nn_renamed RENAME COLUMN before_rename TO after_rename;

-- a sequence that would read as serial, on a not-null that serial cannot write
CREATE TABLE app.nn_seq_unchecked (id int);
ALTER TABLE app.nn_seq_unchecked ADD CONSTRAINT nn_seq_unchecked_named NOT NULL id NOT VALID;
CREATE SEQUENCE app.nn_seq_unchecked_id_seq AS int OWNED BY app.nn_seq_unchecked.id;
ALTER TABLE app.nn_seq_unchecked ALTER COLUMN id SET DEFAULT nextval('app.nn_seq_unchecked_id_seq');
CREATE TABLE app.nn_seq_uninherited (id int NOT NULL NO INHERIT);
CREATE SEQUENCE app.nn_seq_uninherited_id_seq AS int OWNED BY app.nn_seq_uninherited.id;
ALTER TABLE app.nn_seq_uninherited ALTER COLUMN id SET DEFAULT nextval('app.nn_seq_uninherited_id_seq');

-- inheritance: local constraints merged with a parent's, inherited ones, and a parent's NO INHERIT
CREATE TABLE app.nn_base (id int NOT NULL, w int CONSTRAINT nn_base_w NOT NULL, x int);
CREATE TABLE app.nn_kid (id int NOT NULL, w int CONSTRAINT nn_kid_w NOT NULL) INHERITS (app.nn_base);
CREATE TABLE app.nn_heir () INHERITS (app.nn_base);
COMMENT ON CONSTRAINT nn_base_w ON app.nn_heir IS 'an inherited not-null';
ALTER TABLE app.nn_heir ADD CONSTRAINT nn_heir_x NOT NULL x;
ALTER TABLE app.nn_heir ALTER COLUMN id SET NOT NULL;
CREATE TABLE app.nn_unchecked_base (v int);
CREATE TABLE app.nn_unchecked_kid (v int CONSTRAINT nn_unchecked_kid_v NOT NULL) INHERITS (app.nn_unchecked_base);
ALTER TABLE app.nn_unchecked_base ADD CONSTRAINT nn_unchecked_base_v NOT NULL v NOT VALID;
CREATE TABLE app.nn_unchecked_joiner (v int);
ALTER TABLE app.nn_unchecked_joiner ADD CONSTRAINT nn_unchecked_joiner_v NOT NULL v NOT VALID;
ALTER TABLE app.nn_unchecked_joiner INHERIT app.nn_unchecked_base;
CREATE TABLE app.nn_identity_kid (id int CONSTRAINT nn_identity_kid_id NOT NULL NO INHERIT) INHERITS (app.plain);
ALTER TABLE app.nn_identity_kid ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY;
CREATE TABLE app.nn_m1 (v int CONSTRAINT nn_m1_v NOT NULL);
CREATE TABLE app.nn_m2 (v int CONSTRAINT nn_m2_v NOT NULL);
CREATE TABLE app.nn_both () INHERITS (app.nn_m1, app.nn_m2);
CREATE TABLE app.nn_loose (v int);
CREATE TABLE app.nn_second () INHERITS (app.nn_loose, app.nn_m2);
CREATE TABLE app.nn_ni (v int NOT NULL NO INHERIT);
CREATE TABLE app.nn_ni_none () INHERITS (app.nn_ni);
CREATE TABLE app.nn_ni_declared (v int NOT NULL) INHERITS (app.nn_ni);
CREATE TABLE app.nn_ni_set () INHERITS (app.nn_ni);
ALTER TABLE app.nn_ni_set ALTER COLUMN v SET NOT NULL;

-- partitions: constraints of their own, a copy with a comment, and copies that keep a name or a
-- NOT VALID state a replay cannot
CREATE TABLE app.nnp (id int NOT NULL, v int, u int, k int) PARTITION BY LIST (k);
CREATE TABLE app.nnp_own PARTITION OF app.nnp (CONSTRAINT nnp_own_id NOT NULL id, CONSTRAINT nnp_own_v NOT NULL v) FOR VALUES IN (1);
ALTER TABLE app.nnp_own ADD CONSTRAINT nnp_own_u NOT NULL u NOT VALID;
CREATE TABLE app.nnp_copy PARTITION OF app.nnp FOR VALUES IN (2);
COMMENT ON CONSTRAINT nnp_id_not_null ON app.nnp_copy IS 'a partition''s copy';
CREATE TABLE app.nnp_set PARTITION OF app.nnp FOR VALUES IN (3);
ALTER TABLE app.nnp_set ALTER COLUMN v SET NOT NULL;
CREATE TABLE app.nnv (id int, k int) PARTITION BY LIST (k);
CREATE TABLE app.nnv_early PARTITION OF app.nnv FOR VALUES IN (1);
ALTER TABLE app.nnv ADD CONSTRAINT nnv_id NOT NULL id NOT VALID;
COMMENT ON CONSTRAINT nnv_id ON app.nnv_early IS 'a comment the replay cannot place';
CREATE TABLE app.nnv_late PARTITION OF app.nnv FOR VALUES IN (2);

CREATE TABLE app.nn_pets OF app.pet (CONSTRAINT nn_pets_id NOT NULL id, kind WITH OPTIONS NOT NULL, name WITH OPTIONS DEFAULT 'x');
ALTER TABLE app.nn_pets ADD CONSTRAINT nn_pets_name NOT NULL name NOT VALID;
CREATE FOREIGN TABLE app.nn_remote (a int CONSTRAINT nn_remote_a NOT NULL, b int, c int NOT NULL) SERVER hostile_server;
ALTER FOREIGN TABLE app.nn_remote ADD CONSTRAINT nn_remote_b NOT NULL b NOT VALID;
CREATE TABLE app.nn_gen (
  a int,
  plain int GENERATED ALWAYS AS (a * 2) VIRTUAL,
  required int GENERATED ALWAYS AS (a * 3) VIRTUAL NOT NULL,
  named int GENERATED ALWAYS AS (a * 4) VIRTUAL CONSTRAINT nn_gen_named NOT NULL
);

CREATE TABLE app.ne (
  id int,
  ref int,
  CONSTRAINT ne_chk CHECK (id > 0) NOT ENFORCED,
  CONSTRAINT ne_fk FOREIGN KEY (ref) REFERENCES app.refd NOT ENFORCED
);
CREATE TABLE app.temporal (id int, during daterange, CONSTRAINT temporal_pkey PRIMARY KEY (id, during WITHOUT OVERLAPS));
CREATE TABLE app.temporal_ref (id int, during daterange, CONSTRAINT temporal_ref_fk FOREIGN KEY (id, PERIOD during) REFERENCES app.temporal (id, PERIOD during));
